const SchemasAdaptersBigqueryV0ConnectionSchemaPrioritySchema = z
  .enum(['interactive', 'batch'])
  .openapi({ title: 'Priority', description: 'An enumeration.' })
  .openapi('SchemasAdaptersBigqueryV0ConnectionSchemaPriority')

const BigqueryConnectionSchema = z
  .object({
    project_id: z.string().min(1).max(255).openapi({ title: 'Project Id' }),
    timeout_seconds: z.int().gt(0).max(86400).openapi({ title: 'Timeout Seconds' }),
    private_key_id: z.string().min(1).max(255).openapi({ title: 'Private Key Id' }),
    private_key: z.string().openapi({ title: 'Private Key', writeOnly: true }),
    client_email: z.string().min(1).max(1024).openapi({ title: 'Client Email' }),
    client_id: z.string().min(1).max(255).openapi({ title: 'Client Id' }),
    auth_uri: z.string().openapi({ title: 'Auth Uri' }),
    token_uri: z.string().openapi({ title: 'Token Uri' }),
    auth_provider_x509_cert_url: z.string().openapi({ title: 'Auth Provider X509 Cert Url' }),
    client_x509_cert_url: z.string().openapi({ title: 'Client X509 Cert Url' }),
    priority: SchemasAdaptersBigqueryV0ConnectionSchemaPrioritySchema.exactOptional(),
    scopes: z.array(z.string()).exactOptional().openapi({ title: 'Scopes' }),
    location: z.string().min(1).max(255).exactOptional().openapi({ title: 'Location' }),
    maximum_bytes_billed: z.int().exactOptional().openapi({ title: 'Maximum Bytes Billed' }),
    execution_project: z.string().exactOptional().openapi({ title: 'Execution Project' }),
    impersonate_service_account: z
      .string()
      .exactOptional()
      .openapi({ title: 'Impersonate Service Account' }),
    retries: z.int().min(0).max(60).default(1).exactOptional().openapi({ title: 'Retries' }),
    job_retry_deadline_seconds: z
      .int()
      .exactOptional()
      .openapi({ title: 'Job Retry Deadline Seconds' }),
    job_creation_timeout_seconds: z
      .int()
      .exactOptional()
      .openapi({ title: 'Job Creation Timeout Seconds' }),
    application_id: z
      .string()
      .exactOptional()
      .openapi({ title: 'Application Id', writeOnly: true }),
    application_secret: z
      .string()
      .exactOptional()
      .openapi({ title: 'Application Secret', writeOnly: true }),
    gcs_bucket: z.string().exactOptional().openapi({ title: 'Gcs Bucket' }),
    dataproc_region: z.string().exactOptional().openapi({ title: 'Dataproc Region' }),
    dataproc_cluster_name: z.string().exactOptional().openapi({ title: 'Dataproc Cluster Name' }),
    api_endpoint: z.string().exactOptional().openapi({ title: 'Api Endpoint' }),
  })
  .openapi({
    title: 'BigqueryConnection',
    required: [
      'project_id',
      'timeout_seconds',
      'private_key_id',
      'private_key',
      'client_email',
      'client_id',
      'auth_uri',
      'token_uri',
      'auth_provider_x509_cert_url',
      'client_x509_cert_url',
    ],
  })
  .openapi('BigqueryConnection')

const DeploymentEnvironmentAuthTypeSchema = z
  .enum(['service-account-json', 'external-oauth-wif'])
  .openapi({ title: 'DeploymentEnvironmentAuthType', description: 'An enumeration.' })
  .openapi('DeploymentEnvironmentAuthType')

const SchemasAdaptersBigqueryV1ConnectionSchemaPrioritySchema = z
  .enum(['interactive', 'batch'])
  .openapi({ title: 'Priority', description: 'An enumeration.' })
  .openapi('SchemasAdaptersBigqueryV1ConnectionSchemaPriority')

const BigqueryConnectionV1Schema = z
  .object({
    deployment_env_auth_type:
      DeploymentEnvironmentAuthTypeSchema.default('service-account-json').exactOptional(),
    project_id: z.string().min(1).max(255).openapi({ title: 'Project Id' }),
    private_key_id: z.string().max(255).exactOptional().openapi({ title: 'Private Key Id' }),
    private_key: z.string().exactOptional().openapi({ title: 'Private Key', writeOnly: true }),
    client_email: z.string().max(1024).exactOptional().openapi({ title: 'Client Email' }),
    client_id: z.string().max(255).exactOptional().openapi({ title: 'Client Id' }),
    auth_uri: z.string().exactOptional().openapi({ title: 'Auth Uri' }),
    token_uri: z.string().exactOptional().openapi({ title: 'Token Uri' }),
    auth_provider_x509_cert_url: z
      .string()
      .exactOptional()
      .openapi({ title: 'Auth Provider X509 Cert Url' }),
    client_x509_cert_url: z.string().exactOptional().openapi({ title: 'Client X509 Cert Url' }),
    job_execution_timeout_seconds: z
      .int()
      .gt(0)
      .max(86400)
      .exactOptional()
      .openapi({ title: 'Job Execution Timeout Seconds' }),
    priority: SchemasAdaptersBigqueryV1ConnectionSchemaPrioritySchema.exactOptional(),
    scopes: z.array(z.string()).exactOptional().openapi({ title: 'Scopes' }),
    location: z.string().min(1).max(255).exactOptional().openapi({ title: 'Location' }),
    maximum_bytes_billed: z.int().exactOptional().openapi({ title: 'Maximum Bytes Billed' }),
    execution_project: z.string().exactOptional().openapi({ title: 'Execution Project' }),
    impersonate_service_account: z
      .string()
      .exactOptional()
      .openapi({ title: 'Impersonate Service Account' }),
    retries: z.int().min(0).max(60).exactOptional().openapi({ title: 'Retries' }),
    job_retry_deadline_seconds: z
      .int()
      .exactOptional()
      .openapi({ title: 'Job Retry Deadline Seconds' }),
    job_creation_timeout_seconds: z
      .int()
      .exactOptional()
      .openapi({ title: 'Job Creation Timeout Seconds' }),
    application_id: z
      .string()
      .exactOptional()
      .openapi({ title: 'Application Id', writeOnly: true }),
    application_secret: z
      .string()
      .exactOptional()
      .openapi({ title: 'Application Secret', writeOnly: true }),
    gcs_bucket: z.string().exactOptional().openapi({ title: 'Gcs Bucket' }),
    dataproc_region: z.string().exactOptional().openapi({ title: 'Dataproc Region' }),
    dataproc_cluster_name: z.string().exactOptional().openapi({ title: 'Dataproc Cluster Name' }),
    api_endpoint: z.string().exactOptional().openapi({ title: 'Api Endpoint' }),
    adapter_id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        title: 'Adapter Id',
        description: 'Deprecated, use credentials.adapter_version',
      }),
  })
  .openapi({ title: 'BigqueryConnectionV1', required: ['project_id'] })
  .openapi('BigqueryConnectionV1')

